function escapeHTMLchar(str) {
  return str.replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;")
}
$('.cf-mobile-grid-layout__answer-content .cf-list__item').filter(function(){
    return $(this).has('.exclusive_item_grid').length > 0;
}).eq(0).css('margin-top', DKREF_MARGIN)


