    {
        var count = 0;
        var str = f(qid).get();
        str = str.replace(/^\s+|\s+$/g, '');
        var regex = /^[0123456789!_@#£$%`^&* +=,. ()\/{}|;:<>?~-]$/;
        for (var i = 0; i < str.length; i++) {
            if (regex.test(str[i])) {
                count++
            }
        }
        if(str.length<4)
        {
             errormessage('23');
        }

        if (count == str.length) {
            errormessage('22');
        }
    }
}

