//copied from CSAM since the one above in SRC_Shell is wrong
function maskingAM_FLAG() {
    var st = set(); // Initialize an empty set
    if (!f('AM_flag_count').toBoolean()) {
        f('AM_flag_count').set(0)
        SetRespondentValue('AM_flag_count',0)
    }    
    var count = parseInt(f('AM_flag_count').get(), 10); // Convert open-end to number

    if (count === 0) {
        st = set('1', '2', '3');
    } else if (count === 1) {
        st = set('1', '2', '4');
        //st = set('1', '2'); //Only leave 1 message - this does not apply for this job
    } else if (count >= 2) {
        st = set('1', '2');
    }

    return st;
}

