}


//ALOTE=1 - 35 LOTE - no follow up
if (f('ALOTE').any('1')) {
    f('FinalOutcome').set('4'); //LOTE no follow up
    SetExtendedStatus('35')
}

//Other contacts: 71-80
//ADIS=1 - 71 Unable to complete due to disability
if (f('ADIS').any('1')) {
    f('FinalOutcome').set('5'); //Physically or mentally unable/incompetent
    SetExtendedStatus('71')
}

//OUT OF SCOPE
//S2=3 OR 4 - 81 Did not do specified course/subject at specified institution - CP updated
if (f('S2').any('3','4')) {
    f('FinalOutcome').set('6'); //Out of scope
    SetExtendedStatus('81')
}
//S2=5 - 82 Not a student
if (f('S2').any('5')) {
    f('FinalOutcome').set('6'); //Out of scope
    SetExtendedStatus('82')
}
//s2=6 - 83 Training completed before 2025
if (f('S2').any('6')) {
    f('FinalOutcome').set('6'); //Out of scope
    SetExtendedStatus('83')
}



//Screen out: 81-90
/*if (f('Count_Name').toNumber()>=3) {
    f('FinalOutcome').set('9'); //REF_SCHOOL (if three times invalid)
    SetExtendedStatus('81')
}*/

//CP updated (copied from GOS L PFR)
//ES - updated to match email1=3 and allterm outcome in word doc so set to 93
//Email bounced – no other emails
if (f('BOUNCE').any('2')) {
    f('FinalOutcome').set('3'); //Out of scope
    SetExtendedStatus('93')
}

//Refusal: 91-100
//INTRO=2  - 91 Household Refusal
if (f('INTRO1').any('2')) {
    f('FinalOutcome').set('2'); //Household refusal
    SetExtendedStatus('91')
}
//INTRO=3 or S2=2 - 94 Refused at mobile safety question - CP updated
if (f('INTRO1').any('3') || f('S2').any('2')) {
    f('FinalOutcome').set('3'); //Respondent refusal
    SetExtendedStatus('94')
}
// CP note: this had a separate outcome in dimensions
//SAFE1=3 or MOBAPPT=3 -92 Respondent Refusal
if (f('SAFE1').any('3') || f('MOBAPPT').any('3')) {
    f('FinalOutcome').set('3'); //Known respondent refusa
    SetExtendedStatus('92')
}
//EMAIL1=3 or BOUNCE=2 - 93 Refused to provide email address 
//if (f('EMAIL1').any('3') || f('BOUNCE').any('2')) {
    if (f('EMAIL1').any('3')) {
    f('FinalOutcome').set('3'); //Respondent refused email address
    SetExtendedStatus('93')
}

//[WG]
//Q1=999 - 84 Refused Q1
//if (f('Q1').any('999')) {
if (f('extended_status').any('84')) {
    f('FinalOutcome').set('3'); //Resp refusal
    SetExtendedStatus('84')
}
//[WG]
//Q4=999 - 85 Refused Q4
//if (f('Q4').any('999')) {
if (f('extended_status').any('85')) {
    f('FinalOutcome').set('3'); //Resp refusal
    SetExtendedStatus('85')
}

//Update queue, previous_queue, has_made_contact, screener sample fields
//Completed
if (GetExtendedStatus() == 13) {
    SetRespondentValue('queue','COMPLETED');
    SetRespondentValue('has_made_contact','1');
}
//No answer
else if (GetExtendedStatus() == 3) {
    SetRespondentValue('queue','RECALL');
}
//Answering machine - message left
else if (GetExtendedStatus() == 7) {
    SetRespondentValue('queue','RECALL');
} 
//Answering machine - No message left
else if (GetExtendedStatus() == 50) {
    SetRespondentValue('queue', 'RECALL');
}
//Engaged/busy
else if (GetExtendedStatus() == 2) {
    SetRespondentValue('queue','RECALL');
}
//LOTE - follow up required
else if (GetExtendedStatus() == 36) {
    SetRespondentValue('queue','RECALL');
    SetRespondentValue('has_made_contact','1');
    SetRespondentValue('lote_flag','1')
}
//Hard Appointment
else if (GetExtendedStatus() == 1) {
    SetRespondentValue('queue','APPOINTMENT');
    SetRespondentValue('has_made_contact','1');
}
//Soft Appointment
else if (GetExtendedStatus() == 33) {
    SetRespondentValue('queue','APPOINTMENT');
    SetRespondentValue('has_made_contact','1');
}
//Respondent refusal: 5, 91-100
else if (GetExtendedStatus() == 5 || (GetExtendedStatus() >= 91 && GetExtendedStatus() <= 100)) {
    SetRespondentValue('queue','REFUSED');
    SetRespondentValue('has_made_contact','1');
    SetRespondentValue('screener','Failed');
    SetStatus("screened");
}
//Over quota
else if (GetExtendedStatus() == 4) {
    SetRespondentValue('queue','OVERQUOTA');
    SetRespondentValue('screener','Failed');
}
//Survey script error
else if (GetExtendedStatus() == 1051) {
    SetRespondentValue('queue','FAILED');
    SetRespondentValue('has_made_contact','1');
}
//Agreed to complete online
else if (GetExtendedStatus() == 20) {
    SetRespondentValue('queue','TRANSFER_TO_WEB');
    SetRespondentValue('has_made_contact','1');
}
//UNUSABLE
//Fax
else if (GetExtendedStatus() == 9) {
    SetRespondentValue('queue','UNUSABLE');
    SetRespondentValue('has_made_contact','0');
}
//Number disconnected
else if (GetExtendedStatus() == 11) {
    SetRespondentValue('queue','UNUSABLE');
    SetRespondentValue('has_made_contact','0');
}
//Deceased
else if (GetExtendedStatus() == 40) {
    SetRespondentValue('queue','UNUSABLE');
    SetRespondentValue('has_made_contact','1');
    SetStatus("screened");
}
//Business number/Not a residential number
else if (GetExtendedStatus() == 60) {
    SetRespondentValue('queue','UNUSABLE');
    SetRespondentValue('has_made_contact','1');
}
//RESIDENTIAL_NUMBER/Not a business number
else if (GetExtendedStatus() == 61) {
    SetRespondentValue('queue','UNUSABLE');
    SetRespondentValue('has_made_contact','1');
}
//Named person / organisation not known
else if (GetExtendedStatus() == 62) {
    SetRespondentValue('queue','UNUSABLE');
    SetRespondentValue('has_made_contact','1');
}
//Midway termination
else if (GetExtendedStatus() == 6) {
    SetRespondentValue('queue','UNUSABLE');
    SetRespondentValue('has_made_contact','1');
    SetStatus("screened");
}
//DNCR/Remove number from list
else if (GetExtendedStatus() == 17) {
    SetRespondentValue('queue','UNUSABLE');
    SetRespondentValue('has_made_contact','1');
    SetStatus("screened");
}
//Not available/Away for duration
else if (GetExtendedStatus() == 34) {
    SetRespondentValue('queue','UNUSABLE');
    SetRespondentValue('has_made_contact','1');
}
//LOTE - no follow up
else if (GetExtendedStatus() == 35) {
    SetRespondentValue('queue','UNUSABLE');
    SetRespondentValue('has_made_contact','1');
    SetRespondentValue('lote_flag','2')
}
//Too old / frail / ill-health
else if (GetExtendedStatus() == 37) {
    SetRespondentValue('queue','UNUSABLE');
    SetRespondentValue('has_made_contact','1');
    SetStatus("screened");
}
//Unreliable respondent / drunk
else if (GetExtendedStatus() == 38) {
    SetRespondentValue('queue','UNUSABLE');
    SetRespondentValue('has_made_contact','1');
    SetStatus("screened");
}
//Claims to have done survey
else if (GetExtendedStatus() == 39) {
    SetRespondentValue('queue','UNUSABLE');
    SetRespondentValue('has_made_contact','1');
}
//No-one 18 plus in household
else if (GetExtendedStatus() == 41) {
    SetRespondentValue('queue','UNUSABLE');
    SetRespondentValue('has_made_contact','1');
    SetRespondentValue('screener','Failed');
}
//Incoming call restriction
else if (GetExtendedStatus() == 56) {
    SetRespondentValue('queue','UNUSABLE');
    SetRespondentValue('has_made_contact','0');
}
//FailedScreener: 81 to 90
else if (GetExtendedStatus() == 14 || (GetExtendedStatus()>=81 && GetExtendedStatus()<=90)) {
    SetRespondentValue('queue','UNUSABLE');
    SetRespondentValue('has_made_contact','1');
    SetRespondentValue('screener','Failed');
    SetStatus("screened");
}
//Other contacts (within survey script): 71 to 80
else if (GetExtendedStatus()>=71 && GetExtendedStatus()<=80) {
    SetRespondentValue('queue','UNUSABLE');
    SetRespondentValue('has_made_contact','1');
    SetRespondentValue('screener','Failed');
    SetStatus("screened");
}
//Early complete
if (GetRespondentValue("EarlyCompFlg")=="Y") {
    SetRespondentValue('queue','COMPLETED');
    SetRespondentValue('has_made_contact','1');
};


f('queue').set(GetRespondentValue('queue'));
f('has_made_contact').set(GetRespondentValue('has_made_contact'));
f('screener').set(GetRespondentValue('screener'));

//var iter = f('TotalAttempts').get();
//var iter = GetTotalAttempts();
var iter = f('total_attempt_count');
iter = iter * 1;

// do Duration
var start = new Date(InterviewStart().getTime());
var now = new Date();
var duration = (now.getTime() - start.getTime()) / 1000;
f('session_duration',iter).set(Math.round(duration));

// update interview mode
//f('interview_mode',iter).set(GetSurveyChannel()=="Cati" ? '2' : '1');

// do ExtendedStatus
if (GetExtendedStatus()>=1)
{
    f('contact_extended_status',iter).set(GetExtendedStatus());
    f('LastContactExtendedStatus').set(f('contact_extended_status',iter).valueLabel());
    SetRespondentValue ('extended_status',GetExtendedStatus());
    f('extended_status').set(GetExtendedStatus());
}

// update endQ
f('session_endQ',iter).set(f('endQ'));

//CATI only fields
if (GetSurveyChannel()=="Cati"|| f("Mode").get()=="2")
{
    // do Interviewer ID
    f('call_inter_ID',iter).set(GetCatiInterviewerId());

    // do Interviewer Name/login
    f('call_inter_name',iter).set(GetCatiInterviewerName());

    // do Comments
    if (f('Comments').toBoolean())
    {
        f('call_comments',iter).set(f('Comments'));
        f('Comments').set(null); 
    }

    //call_ref_rr1
    if (f('RR1').toBoolean()) 
    {
        f('call_ref_rr1',iter).set(f('RR1').valueLabel());
    }

    //call_ref_rr2
    if (f('RR2').toBoolean()) 
    {
        if (f('RR2').any('1')) {
            f('call_ref_rr2',iter).set('Hard refusal');
        }
        else if (f('RR2').any('2')) {
            f('call_ref_rr2',iter).set('Soft refusal');
        }    
    }

    //call_Ref_con
    f('call_ref_con',iter).set(f('ref_con'));    
}


// Apptime
if (GetExtendedStatus()==1 || GetExtendedStatus()==33 || GetExtendedStatus()==32)
{
    f('call_app_time',iter).set(GetCatiAppointmentTime())
}
else
{
    f('call_app_time',iter).set(null)
}

function Authenticate() {

    var clientId = "redacted";
    var clientSecret = "redacted";
    var auendpoint = "https://surveys.srcentre.com.au/identity/connect/token";
    var data = "client_id=" + clientId + "&client_secret="redacted"&grant_type=api-user&scope=pub.surveys pub.notifications";
    var result = Http.Post(auendpoint, data, null);

    var decoded = JSON.parse(result);
    if (!decoded.access_token || decoded.access_token == null || decoded.access_token == undefined) {
        return null;
    }
    return decoded.access_token;

}

function UpdateResponseData(surveyId,respId,extendedStatus) {
    try{
        var access_token = Authenticate();
        var endpoint = "https://surveys.srcentre.com.au/v1/surveys/" + surveyId + "/responses/data";
        var headers = {
            "Authorization": "redacted" + access_token,
            "Content-Type": "application/json"
        };

        var payload = {
            "dataSchema": {
                "keys": ["respid"],
                "variables": ["respid", "status", "extended_status"]
            },
            "data": [ 
                {
                    "respid": respId, 
                    "status": "screened",
                    "extended_status": extendedStatus
                }
            ],
            "linkRespondentsWithKey": true, //If true, this property will re-use existing respids from the respondent table for records that match the given value. Note! The key-variable must be specified with a FieldWidth.
            "touchLinkedRespondents": true //If true, this property will cause the LastUpdated field on the linked respondent to be updated.
        };

        //Merge Responses API - The PATCH operation will update all records that have a matching key, and will add any records with a key that does not matching existing data.
        var result = Http.PatchJson(endpoint, payload, headers);

        //Response.Write("HTTP result type: " + typeof result + "<br>"); 
        //Response.Write("HTTP result: " + result + "<br>"); 

        //var resultJson = JSON.parse(result);
        //Response.Write("resultJson: " + JSON.stringify(resultJson) + "<br>");         

        return result;

    } catch (e) {
        //f("returnedData").set(e);
        return false;
    }
}

//respid will get from sample field main_respid
function UpdateRespondentData(surveyId, respId, extendedStatus) {
     try{

            //add a variable to capture current date & time into date now
            //var date_now = new Date(); 
            //var offSet = 11 
            ////var offSet = 10 //Daylight saving enabled
            //var offsetUTC = offSet*60*60*1000; 
            //var aus_date_now = new Date(date_now.getTime()+offsetUTC); 

            var access_token = Authenticate();

            var endpoint = "https://surveys.srcentre.com.au/v1/surveys/" + surveyId + "/respondents/data";

            var headers = {
                "Authorization": "redacted" + access_token,
                "Content-Type": "application/json"
            };

            var integrations_obj = {
                source: "CATI integration",
                extended_status: extendedStatus
            };

            var payload = {
                "schedulingMode": "full",
                "dataSchema": {
                    "keys": ["respid"],
                    "variables": ["respid", "extended_status", "queue", "integrations"] //Case sensitive, make sure match the respondent table
                    //"variables": ["respid", "extended_status", "queue", "OptOut", "OptOutDate"] //Case sensitive, make sure match the respondent table
                },
                "data": [
                    {
                        "respid": respId,
                        "extended_status": extendedStatus,
                        "queue": "UNUSABLE",
                        "integrations": JSON.stringify(integrations_obj)
                        //"OptOut": "6", //The respondent chose to opt out of all surveys for the project after receiving the survey invitation.
                        //"OptOutDate": aus_date_now
                    }
                    ]
                };

            // Update respondent data API: https://au.hxplatform.com/docs/public-apis/current/apis/surveys/api-explorer.html#/operations/UpdateRespondentData
            var result = Http.PutJson(endpoint, payload, headers);

            // Merge respondent data API
            // var result = Http.PatchJson(endpoint, payload, headers);

            //Response.Write("Update respondent data result<br>"); 
            //Response.Write("HTTP result type: " + typeof result + "<br>"); 
            //Response.Write("HTTP result: " + result + "<br>"); 

            return result;

        } catch (e) {

            return e;

        }
}

